#!/bin/bash\n\n# Cloudflare D1 Setup Script\n# Este script configura completamente la base de datos para 1M de artículos\n\nset -e\n\necho \"🚀 Iniciando configuración de Cloudflare D1...\"\necho \"\"\n\n# 1. Verificar que wrangler está instalado\necho \"📦 Verificando Wrangler CLI...\"\nif ! command -v wrangler &> /dev/null; then\n    echo \"❌ Wrangler no está instalado. Instálalo con: npm install -g @cloudflare/wrangler\"\n    exit 1\nfi\necho \"✅ Wrangler está instalado\"\necho \"\"\n\n# 2. Autenticarse en Cloudflare\necho \"🔐 Verificando autenticación en Cloudflare...\"\nif ! wrangler whoami &> /dev/null; then\n    echo \"⚠️  No estás autenticado. Ejecutando: wrangler login\"\n    wrangler login\nelse\n    echo \"✅ Autenticación confirmada\"\nfi\necho \"\"\n\n# 3. Crear esquema en D1\necho \"📊 Creando esquema en D1 (database_id: 476f34d4-5622-4a56-923e-c4fb571578c2)...\"\nwrangler d1 execute linguafly_db --file=./src/lib/db/schema.sql --remote\necho \"✅ Esquema creado exitosamente\"\necho \"\"\n\n# 4. Generar tipos TypeScript\necho \"🔧 Generando tipos TypeScript para Cloudflare...\"\nnpm run cf-typegen\necho \"✅ Tipos generados\"\necho \"\"\n\n# 5. Información de deployment\necho \"📋 Próximos pasos:\"\necho \"\"\necho \"1. Configurar .env:\"\necho \"   cp .env.example .env\"\necho \"   # Editar .env con tu API_KEY\"\necho \"\"\necho \"2. Deploy a Cloudflare:\"\necho \"   npm run cf:deploy\"\necho \"\"\necho \"3. Importar artículos (después de deploy):\"\necho \"   npx tsx scripts/bulk-import-articles.ts articles.jsonl\"\necho \"\"\necho \"4. Verificar deployment:\"\necho \"   curl https://linguafly.dev/health\"\necho \"   curl https://linguafly.dev/api/articles/count\"\necho \"\"\necho \"✅ ¡Configuración completada!\"\n